// Файл собран скриптом trainer/собрать-банк.py — правки вносите в источники.
window.ТЕМЫ = [{"n": 0, "название": "Времена и согласование времён"}, {"n": 1, "название": "Условные предложения и модальные глаголы"}, {"n": 2, "название": "Инфинитив, герундий и управление глагола"}, {"n": 3, "название": "Простое предложение, придаточные и косвенная речь"}, {"n": 4, "название": "Местоимения, определители, артикли"}, {"n": 5, "название": "Степени сравнения и наречия"}, {"n": 6, "название": "Словообразование и паронимы"}, {"n": 7, "название": "Лексика и устойчивые сочетания"}, {"n": 8, "название": "Соответствие: дефиниции понятий"}, {"n": 9, "название": "Числительные, даты и величины"}];
window.БАНК = [
{"id": "en-0001", "t": 3, "ty": "one", "q": "I couldn't make ... what ... about.", "qru": "Я не мог разобрать, о чём они говорили.", "oru": ["make in — такого фразового глагола нет; did the talk — вопросительный порядок слов", "make out — разобрать, понять; they were talking — они говорили", "make through — такого фразового глагола нет; they are talking — они говорят (сейчас)", "make off — сбежать, смыться; were they talking — вопросительный порядок слов"], "pairsru": [], "poolru": {}, "o": ["in ... did the talk", "out ... they were talking", "through ... they are talking", "off ... were they talking"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Полное предложение: I couldn't make out what they were talking about — «я не мог разобрать, о чём они говорили». Первый пропуск — фразовый глагол make out «разобрать, различить, понять на слух». Второй пропуск — придаточное после what: это косвенный вопрос, а в нём всегда прямой порядок слов (подлежащее перед сказуемым) и никакого вспомогательного do. Время придаточного согласуется с прошедшим couldn't, поэтому were talking, а не are talking. Предлог about в конце относится к what: talk about something.", "w": ["make in как фразовый глагол не существует, а did the talk сохраняет вопросительный порядок внутри придаточного, где он запрещён.", "", "make through нет — есть get through и make it through («пережить, справиться»), и оба о другом. Плюс are talking нарушает согласование времён с couldn't.", "make off существует, но значит «удрать, скрыться» (make off with the money) и не берёт придаточное. Главная ловушка здесь — инверсия were they talking: она выглядит «вопросительной», но в косвенном вопросе недопустима."], "k": "Косвенный вопрос — уже не вопрос: порядок слов прямой, do исчезает. А make out — это «разглядеть/расслышать»: out = выудить смысл наружу."},
{"id": "en-0002", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["факты или подробности, которые сообщают что-то о ситуации, человеке, событии и т. п.", "высказывание о том, что, по вашему мнению, произойдёт, или сам факт такого высказывания", "общее изменение или развитие в определённом направлении", "внимательное изучение чего-либо, чтобы лучше это понять", "способ что-то делать, особенно правильный или общепринятый порядок действий", "сказать противоположное тому, что сказал кто-то другой"], "poolru": {"-": "нет подходящего понятия", "analysis": "анализ, разбор", "information": "информация, сведения", "procedure": "процедура, порядок действий", "tendency": "тенденция"}, "o": [], "a": [], "pairs": [{"l": "facts or details that tell you something about a situation, person, event etc.", "r": "information"}, {"l": "a statement about what you think is going to happen, or the act of making this statement", "r": "-"}, {"l": "a general change or development in a particular direction", "r": "tendency"}, {"l": "a careful examination of something in order to understand it better", "r": "analysis"}, {"l": "a way of doing something, especially the correct or usual way", "r": "procedure"}, {"l": "to say the opposite of what someone else has said", "r": "-"}], "pool": ["-", "analysis", "information", "procedure", "tendency"], "ans": "", "img": null, "oimg": [], "e": "Четыре понятия на шесть определений: два определения остаются с прочерком. information — сведения о ситуации, человеке, событии; tendency — общее изменение в определённом направлении; analysis — тщательный разбор ради понимания; procedure — принятый порядок действий. Строка 2 описывает prediction (высказывание о будущем), строка 6 — глагол to contradict; ни одного из этих слов в списке нет, поэтому «-». Подсказка по строке 6: определение начинается с to say, то есть описывает глагол, а все понятия в списке — существительные.", "w": [], "k": "Идти от определения к слову, а не наоборот: сначала назови слово сам, потом ищи его в списке. Если слова там нет — это и есть прочерк."},
{"id": "en-0003", "t": 7, "ty": "one", "q": "The Suez ... was built in the second half of the nineteenth century.", "qru": "Суэцкий канал был построен во второй половине девятнадцатого века.", "oru": ["channel — пролив; естественное русло; телеканал", "canal — канал, вырытый людьми", "bay — бухта, небольшой залив", "gulf — крупный морской залив"], "pairsru": [], "poolru": {}, "o": ["channel", "canal", "bay", "gulf"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Canal — искусственный водный путь, прорытый людьми: the Suez Canal, the Panama Canal. Ключевое слово в предложении — was built: построить можно только рукотворный объект. Суэцкий канал прорыт в 1859-1869 годах, то есть действительно во второй половине XIX века.", "w": ["channel — природный пролив между участками суши (the English Channel) или русло; он существует сам по себе, его не строят.", "", "bay — залив, бухта, вдающаяся в сушу; природный объект, и по смыслу Суэц соединяет два моря, а не вдаётся в берег.", "gulf — крупный залив (the Persian Gulf, the Gulf of Mexico); тоже природное образование."], "k": "Built → рукотворное → canal. Channel природа прорыла сама, canal прорыли люди."},
{"id": "en-0004", "t": 7, "ty": "one", "q": "Where do you ... ? – I'm from Chile.", "qru": "Откуда вы родом? — Я из Чили.", "oru": ["come back from — возвращаться откуда-либо", "come from — быть родом из", "return from — возвращаться из", "come to — приходить куда-либо"], "pairsru": [], "poolru": {}, "o": ["come back from", "come from", "return from", "come to"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Where do you come from? — устойчивый вопрос о происхождении, и ответ I'm from Chile отвечает именно на него. Present Simple здесь про постоянный факт (откуда человек родом), а не про разовое перемещение.", "w": ["come back from — «вернуться откуда-то» из конкретной поездки; ответ был бы вроде I've just come back from Chile, а не I'm from Chile.", "", "return from — то же значение возвращения, только книжнее; тоже требует контекста поездки.", "come to — направление «куда», а не «откуда»; с ответом I'm from Chile не стыкуется."], "k": "From в вопросе и from в ответе должны совпасть: Where do you come FROM — I'm FROM Chile."},
{"id": "en-0005", "t": 4, "ty": "one", "q": "Can I give you ... ?", "qru": "Можно дать вам совет?", "oru": ["an advice — «совет» с артиклем, хотя advice неисчисляемо", "a piece of advice — один совет", "some advices — несколько советов, во множественном числе", "a few advice — немного советов"], "pairsru": [], "poolru": {}, "o": ["an advice", "a piece of advice", "some advices", "a few advice"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Advice — неисчисляемое существительное: у него нет множественного числа и оно не берёт артикль a/an. Чтобы посчитать порцию неисчисляемого, используют партитив a piece of: a piece of advice, two pieces of advice. По той же модели работают a piece of information, a piece of news, a piece of furniture.", "w": ["an advice — неисчисляемое не сочетается с неопределённым артиклем.", "", "some advices — формы множественного числа advices не существует.", "a few сочетается только с исчисляемыми во множественном числе (a few books); с неисчисляемым говорят a little advice."], "k": "Advice, information, news, furniture — все считаются «кусками»: a piece of. Артикль лепится к piece, а не к самому слову."},
{"id": "en-0006", "t": 3, "ty": "one", "q": "I've been ... anything about the results of the examination.", "qru": "Мне велели ничего не говорить о результатах экзамена.", "oru": ["said not to tell nobody — «сказали никому не рассказывать», с двойным отрицанием", "told not say anybody — «велели не говорить никому», без частицы to", "said to say nobody about — «сказали никому не говорить о»", "told not to say — велели не говорить"], "pairsru": [], "poolru": {}, "o": ["said not to tell nobody", "told not say anybody", "said to say nobody about", "told not to say"], "a": [3], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Полное предложение: I've been told not to say anything — «мне велели ничего не говорить о результатах экзамена». Пассив здесь строится только от tell: tell somebody to do something → somebody is told to do something. Say адресата без предлога не берёт, поэтому I've been said не существует. Отрицание в косвенном побуждении ставится частицей not перед to-инфинитивом: told not to say. И раз отрицание уже есть, дополнение — anything, а не nobody: двух отрицаний в одном предложении английский не допускает.", "w": ["I've been said не употребляется, и вдобавок not ... nobody — двойное отрицание.", "Пропущена частица to перед инфинитивом (told not to say), а tell anybody значило бы «сказать кому-то», а не «сказать что-то».", "Та же ошибка с пассивом от say плюс nobody вместо anything.", ""], "k": "Пассив строится от tell, не от say: I was told. Запрет в косвенной речи — not to do, а дополнение при отрицании — anything."},
{"id": "en-0007", "t": 6, "ty": "one", "q": "We had to cover the rest of ... ourselves while our teacher was ill.", "qru": "Нам пришлось пройти остаток программы курса самостоятельно, пока наш преподаватель болел.", "oru": ["current — течение; текущий", "contents — содержимое, оглавление", "syllabus — программа учебного курса", "syllable — слог"], "pairsru": [], "poolru": {}, "o": ["current", "contents", "syllabus", "syllable"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Syllabus — программа учебного курса, перечень тем. Cover the syllabus — устойчивое «пройти программу», а the rest of the syllabus — «остаток программы», который студентам пришлось освоить самим, пока болел преподаватель.", "w": ["current — «текущий» как прилагательное или «течение» как существительное; программу так не назовут.", "contents — оглавление или содержимое; the rest of the contents сказали бы про книгу или коробку, а не про курс.", "", "syllable — слог, единица звучащего слова; отличается от syllabus одной буквой, но относится к фонетике."], "k": "Syllabus — программа курса, syllable — слог. Разница в одной букве, но одно про семестр, другое про произношение."},
{"id": "en-0008", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["типичное качество или важная составная часть чего-либо", "официальное выступление на серьёзную тему перед группой людей, особенно студентами", "один из периодов, на которые делится год в колледже или университете", "занятие, на котором преподаватель или специалист вместе с группой изучает и обсуждает предмет", "способность влиять на людей или вещи, а также человек или предмет, обладающий такой способностью", "церемония, на которой дипломы вручают тем, кто окончил университет"], "poolru": {"-": "нет подходящего понятия", "graduation": "выпуск, вручение дипломов", "lecture": "лекция", "semester": "семестр", "seminar": "семинар"}, "o": [], "a": [], "pairs": [{"l": "a typical quality or an important part of something", "r": "-"}, {"l": "a formal talk on a serious subject given to a group of people, especially students", "r": "lecture"}, {"l": "one of the periods into which a year is divided at a college or university", "r": "semester"}, {"l": "an occasion when a teacher or expert and a group of people meet to study and discuss something", "r": "seminar"}, {"l": "the power to have an effect on people or things, or a person or thing that is able to do this", "r": "-"}, {"l": "a ceremony in which degree certificates are given to people who have graduated from a university", "r": "graduation"}], "pool": ["-", "graduation", "lecture", "semester", "seminar"], "ans": "", "img": null, "oimg": [], "e": "Четыре понятия на шесть определений, поэтому два определения останутся с прочерком. lecture — формальное выступление перед аудиторией, прежде всего студенческой; semester — половина учебного года; seminar — занятие, где преподаватель и группа вместе разбирают тему; graduation — церемония вручения дипломов. Определение 1 описывает feature (характерная черта), определение 5 — influence (влияние); ни одного из этих слов в списке нет.", "w": [], "k": "Сначала назови слово сам, потом ищи его в списке. Нет в списке — ставь прочерк, и прочерков может быть несколько."},
{"id": "en-0009", "t": 6, "ty": "one", "q": "Lennon will be remembered for his songs and for his ... sense of humour.", "qru": "Леннона будут помнить за его песни и за его неповторимое чувство юмора.", "oru": ["usual — обычный, привычный", "unique — неповторимый, единственный в своём роде", "inusual — такого слова нет (правильно unusual — необычный)", "visual — зрительный, визуальный"], "pairsru": [], "poolru": {}, "o": ["usual", "unique", "inusual", "visual"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Unique — неповторимый, единственный в своём роде. Запоминают человека именно за то, чего больше ни у кого нет, поэтому will be remembered for his unique sense of humour.", "w": ["usual — «обычный»; за обычное чувство юмора не запоминают, смысл предложения разрушается.", "", "формы inusual в английском не существует — отрицательная приставка к usual даёт unusual.", "visual — «зрительный, наглядный»; к чувству юмора не применяется."], "k": "Отрицание к usual — unusual, а не inusual. И запоминают за unique — то, что неповторимо."},
{"id": "en-0010", "t": 2, "ty": "one", "q": "Finally he asked: \"Have you ... this document?\"", "qru": "Наконец он спросил: «У вас есть возражения против подписания этого документа?»", "oru": ["any objections of signing — возражения «подписания», с предлогом of", "any objections to signing — возражения против подписания", "no any objections to sign — «никаких возражений подписать», с no и any одновременно", "some objections against signing — «некоторые возражения против подписания»"], "pairsru": [], "poolru": {}, "o": ["any objections of signing", "any objections to signing", "no any objections to sign", "some objections against signing"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Objection управляет предлогом to: an objection to something. Здесь to — именно предлог, а не частица инфинитива, поэтому после него идёт герундий: objections to signing. В вопросе с оттенком «есть ли вообще» ставится any, а не some.", "w": ["objection берёт предлог to, а не of.", "", "no и any не сочетаются в одной группе; кроме того, после предлога to нужен герундий signing, а не инфинитив sign.", "предлог against с objection не употребляется, и в вопросе естественнее any, чем some."], "k": "objection TO doing: to здесь предлог, значит дальше -ing. Проверить легко — подставь «to it»: objection to it звучит, значит предлог."},
{"id": "en-0011", "t": 6, "ty": "one", "q": "The council hope to reduce crime in the town by introducing new ... facilities so that people have something to do in the evening.", "qru": "Городской совет надеется снизить преступность, открыв новые общественные заведения, чтобы людям было чем заняться по вечерам.", "oru": ["sociable — общительный (о человеке)", "socialist — социалистический", "slump — резкий спад", "social — общественный, социальный"], "pairsru": [], "poolru": {}, "o": ["sociable", "socialist", "slump", "social"], "a": [3], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Social facilities — общественные учреждения досуга: клубы, спортивные центры, площадки. Именно их создаёт совет, чтобы людям было чем заняться вечером.", "w": ["sociable — «общительный», характеристика человека; учреждения общительными не бывают.", "socialist — «социалистический», политический термин, к досуговой инфраструктуре отношения не имеет.", "slump — существительное «резкий спад»; в позиции определения к facilities не работает.", ""], "k": "social — «общественный», sociable — «общительный». Facilities не умеют быть общительными."},
{"id": "en-0012", "t": 7, "ty": "one", "q": "The business is suffering ... cash flow problems.", "qru": "Компания испытывает серьёзные проблемы с денежным потоком.", "oru": ["obscure — неясный, малоизвестный", "severe — серьёзный, тяжёлый", "obstinate — упрямый", "crony — приятель, кореш"], "pairsru": [], "poolru": {}, "o": ["obscure", "severe", "obstinate", "crony"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Severe — «тяжёлый, острый» о проблемах, боли, погоде, кризисе. Severe cash flow problems — серьёзные трудности с денежным потоком, то есть компании не хватает наличности на текущие платежи.", "w": ["obscure — «малопонятный, малоизвестный»; проблема может быть неясной, но suffer obscure problems не говорят.", "", "obstinate — «упрямый», характеристика человека или, в узком медицинском смысле, неподдающейся болезни.", "crony — существительное «приятель, кум»; в качестве определения к problems не употребляется."], "k": "severe — про силу удара: severe pain, severe weather, severe problems."},
{"id": "en-0013", "t": 3, "ty": "one", "q": "If asked the assistant will tell ... she knows.", "qru": "Если её спросят, помощница расскажет вам всё, что знает.", "oru": ["you everything — вам всё", "to you everything what — «вам всё что», с лишним to и с what вместо that", "it to you all what — «это вам всё что»", "everything that — всё, что (без указания, кому)"], "pairsru": [], "poolru": {}, "o": ["you everything", "to you everything what", "it to you all what", "everything that"], "a": [0], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Tell берёт адресата без предлога и сразу за глаголом: tell you something. Дальше идёт определительное придаточное к everything, союз в котором можно опустить: everything (that) she knows. Получается If asked the assistant will tell you everything she knows — «если её спросить, помощница расскажет вам всё, что знает».", "w": ["", "tell не берёт предлог to перед адресатом (сравни say to you), и после everything ставится that, а не what.", "лишнее местоимение it при уже имеющемся дополнении, и all what — грубая ошибка вместо all that.", "грамматически предложение читается, но теряется адресат you, ради которого и различают tell и say."], "k": "Say TO somebody, но tell somebody — без предлога. После everything союз — that, и его обычно опускают."},
{"id": "en-0014", "t": 7, "ty": "one", "q": "In comparing these interpretations, one finds differences in emphasis as well as fundamental ... .", "qru": "Сравнивая эти толкования, обнаруживаешь различия в акцентах, а также принципиальное сходство.", "oru": ["coverage — охват, освещение темы", "similarities — черты сходства", "likelihood — вероятность", "alike — похожий, одинаково (не существительное)"], "pairsru": [], "poolru": {}, "o": ["coverage", "similarities", "likelihood", "alike"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "As well as соединяет однородные члены, поэтому после него нужно существительное того же ряда, что differences. Естественная пара к «различиям» — similarities, «сходства»: сравнивая трактовки, находишь и различия в акцентах, и принципиальные сходства.", "w": ["coverage — «охват, освещение темы»; с fundamental и в паре с differences не работает.", "", "likelihood — «вероятность»; fundamental likelihood — бессмысленное сочетание.", "alike — прилагательное или наречие «одинаково»; существительным быть не может, а после fundamental нужно существительное."], "k": "As well as соединяет равное с равным: differences ↔ similarities."},
{"id": "en-0015", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["юридическое лицо, отдельное от людей, которые им владеют или управляют", "процесс оценки или определения стоимости бизнеса", "разговор двух или более человек с намерением прийти к взаимному соглашению", "процесс усвоения традиционных ценностей и убеждений", "исключительная лицензия, выдаваемая франчайзинговым компаниям", "сколько что-либо стоит в деньгах или в других товарах, на которые это можно обменять"], "poolru": {"-": "нет подходящего понятия", "corporation": "корпорация", "negotiation": "переговоры", "valuation": "оценка стоимости", "value": "стоимость, ценность"}, "o": [], "a": [], "pairs": [{"l": "a legal entity separate from the persons who own or operate it", "r": "corporation"}, {"l": "the process of assessing or determining the value of a business", "r": "valuation"}, {"l": "a conversation between two or more people with the intention to arrive at a mutual agreement", "r": "negotiation"}, {"l": "the process of incorporating traditional values and beliefs", "r": "-"}, {"l": "an exclusive license given to franchise companies", "r": "-"}, {"l": "how much something is worth in money or other goods for which it can be exchanged", "r": "value"}], "pool": ["-", "corporation", "negotiation", "valuation", "value"], "ans": "", "img": null, "oimg": [], "e": "corporation — юридическое лицо, отделённое от своих владельцев; valuation — процедура определения стоимости бизнеса; negotiation — переговоры ради взаимного соглашения; value — сама стоимость, то, на что вещь можно обменять. Определение 4 описывает acculturation (усвоение традиционных ценностей), определение 5 — franchise; в списке их нет, поэтому обе строки получают прочерк.", "w": [], "k": "value — сколько стоит, valuation — процесс оценки. Суффикс -ation почти всегда указывает на процесс."},
{"id": "en-0016", "t": 5, "ty": "one", "q": "Her new job started ... enough, on the first of February.", "qru": "Её новая работа началась, что весьма кстати, первого февраля.", "oru": ["appropriately — уместно, кстати (наречие)", "appropriate — уместный, подходящий (прилагательное)", "alternatively — или же, в качестве другого варианта", "approximate — приблизительный"], "pairsru": [], "poolru": {}, "o": ["appropriately", "appropriate", "alternatively", "approximate"], "a": [0], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Определяется глагол started, значит нужно наречие. Appropriately enough — устойчивый оборот «что вполне уместно»: новая работа началась, как и положено, первого числа. Enough в таком обороте всегда стоит после наречия или прилагательного.", "w": ["", "appropriate — прилагательное; к глаголу started оно относиться не может.", "alternatively — «как вариант, или же»; вводит альтернативу, которой в предложении нет.", "approximate — прилагательное «приблизительный»; наречие было бы approximately, но и оно по смыслу не подходит к точной дате."], "k": "Определяешь глагол — бери форму на -ly. Enough в этой конструкции идёт следом: appropriately enough."},
{"id": "en-0017", "t": 4, "ty": "one", "q": "... has lived in this house for a long time.", "qru": "Никто не живёт в этом доме уже давно.", "oru": ["Something — что-то (о предмете, не о человеке)", "Some — некоторые (требует существительного после себя)", "Anybody — кто-нибудь", "Nobody — никто"], "pairsru": [], "poolru": {}, "o": ["Something", "Some", "Anybody", "Nobody"], "a": [3], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Nobody has lived in this house for a long time — «в этом доме давно никто не живёт». Nobody уже несёт отрицание, поэтому глагол остаётся в утвердительной форме: второго отрицания английский не допускает. Согласование с nobody — единственное число: has, а не have.", "w": ["Something — «что-то» неодушевлённое; жить в доме оно не может.", "Some — определитель, ему нужно существительное (some people); самостоятельным подлежащим он не бывает.", "Anybody в роли подлежащего употребляется только в вопросах и после отрицания; в утвердительном предложении так не говорят.", ""], "k": "Отрицание в английском одно: Nobody has lived, а не Anybody hasn't lived."},
{"id": "en-0018", "t": 1, "ty": "one", "q": "The owners of the stadium ... its maintenance last year.", "qru": "Должно быть, владельцы стадиона запустили его содержание в прошлом году.", "oru": ["had not to neglect — «не должны были пренебрегать»", "should have neglecting — такой формы не существует", "must have neglected — должно быть, запустили (уверенная догадка о прошлом)", "ought to neglect — следует пренебрегать (о настоящем или будущем)"], "pairsru": [], "poolru": {}, "o": ["had not to neglect", "should have neglecting", "must have neglected", "ought to neglect"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Must have + причастие прошедшего времени — уверенное предположение о прошлом: «должно быть, запустили». Владельцы стадиона, судя по его состоянию, в прошлом году явно не занимались его содержанием. Маркер last year требует отнесённости к прошлому, и только must have neglected её даёт.", "w": ["had not to neglect — такой формы нет: отрицание от had to образуется через didn't have to.", "should have neglecting — после have нужна третья форма глагола (neglected), а не -ing.", "", "ought to neglect — относится к настоящему или будущему и означало бы «следует запустить», что противоречит last year."], "k": "Догадка о прошлом — must have + V3. Ought to и have to говорят про обязанность, а не про вывод."},
{"id": "en-0019", "t": 4, "ty": "one", "q": "... money ... Charitable Fund.", "qru": "Эти деньги принадлежат благотворительному фонду.", "oru": ["That … belongs — то… принадлежит, без предлога to", "These … belong to — эти (множественное число) … принадлежат", "This … belongs to — эти деньги (в английском единственное число) … принадлежат", "Those … are belonging for — те … «принадлежат» в длительном времени и с предлогом for"], "pairsru": [], "poolru": {}, "o": ["That ... belongs", "These ... belong to", "This ... belongs to", "Those ... are belonging for"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Money — неисчисляемое существительное и согласуется как единственное число: this money, belongs. Глагол belong всегда требует предлога to: belong to somebody. Получается This money belongs to Charitable Fund — «эти деньги принадлежат благотворительному фонду».", "w": ["указательное That по числу подходит, но пропущен обязательный предлог to.", "These — множественное число, а money неисчисляемо.", "", "Those — множественное число; belong не употребляется в Continuous, и предлог при нём to, а не for."], "k": "Money — единственное число: this money belongs. Belong всегда TO и никогда не в Continuous."},
{"id": "en-0020", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["найти того или то, что вы ищете, задавая вопросы и собирая сведения", "управлять территорией, городом или страной и их населением", "стать намного хуже или серьёзнее либо сделать таким что-либо", "нарушить закон, правило или соглашение", "повлиять на то, как человек думает или ведёт себя, либо на то, как что-то происходит", "заставить человека почувствовать себя неловко, пристыженно или глупо на людях"], "poolru": {"-": "нет подходящего понятия", "breach": "нарушить (закон, договор)", "embarrass": "смущать, ставить в неловкое положение", "govern": "управлять (страной, городом)", "trace": "выследить, разыскать"}, "o": [], "a": [], "pairs": [{"l": "find someone or something that you are looking for by asking questions and getting information", "r": "trace"}, {"l": "control and manage an area, city, or country and its people", "r": "govern"}, {"l": "become, or make something become, much worse or more serious", "r": "-"}, {"l": "break a law, rule, or agreement", "r": "breach"}, {"l": "affect the way someone thinks or behaves or affect the way something happens", "r": "-"}, {"l": "make someone feel nervous, ashamed, or stupid in a social situation", "r": "embarrass"}], "pool": ["-", "breach", "embarrass", "govern", "trace"], "ans": "", "img": null, "oimg": [], "e": "Все понятия здесь — глаголы, и определения тоже описывают действия. trace — разыскать, выйти на след, расспрашивая и собирая сведения; govern — управлять территорией и её жителями; breach — нарушить закон, правило или договор; embarrass — вогнать в неловкость, смутить. Определение 3 описывает escalate, определение 5 — influence или affect; этих слов в списке нет.", "w": [], "k": "Определение начинается с действия — ищи глагол. Escalate и influence в список не попали, значит две строки останутся пустыми."},
{"id": "en-0021", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["процесс уменьшения чего-либо или величина, на которую что-то уменьшилось", "характер, ощущение или настроение места либо ситуации", "рассмотрение или обсуждение вопроса в устной или письменной форме", "размер или уровень выплаты", "увеличение размера или значимости чего-либо", "круг вопросов, охватываемых книгой, программой, обсуждением, занятием и т. п."], "poolru": {"-": "нет подходящего понятия", "atmosphere": "атмосфера, настроение", "discussion": "обсуждение", "growth": "рост", "scope": "охват, круг вопросов"}, "o": [], "a": [], "pairs": [{"l": "the process of something becoming less, or the amount by which something becomes less", "r": "-"}, {"l": "the character, feeling, or mood of a place or situation", "r": "atmosphere"}, {"l": "the examination or consideration of a matter in speech or writing", "r": "discussion"}, {"l": "an amount or level of payment", "r": "-"}, {"l": "an increase in the size or the importance of something", "r": "growth"}, {"l": "the range of a subject covered by a book, programme, discussion, class, etc.", "r": "scope"}], "pool": ["-", "atmosphere", "discussion", "growth", "scope"], "ans": "", "img": null, "oimg": [], "e": "atmosphere — настроение, которым проникнуто место или ситуация; discussion — разбор вопроса в речи или на письме; growth — рост размера или значимости; scope — охват темы, границы того, что рассматривается. Определение 1 описывает decrease или reduction, определение 4 — rate (ставка, размер оплаты); в списке их нет.", "w": [], "k": "growth — про увеличение, scope — про границы темы. Одно измеряет размер, другое очерчивает рамки."},
{"id": "en-0022", "t": 2, "ty": "one", "q": "It is not worth ... this information into account.", "qru": "Не стоит принимать эту информацию во внимание.", "oru": ["if we took — если бы мы приняли", "taking — принимать (герундий после worth)", "be taking — такой формы здесь быть не может", "totake — слитно написанное to take, «принять»"], "pairsru": [], "poolru": {}, "o": ["if we took", "taking", "be taking", "totake"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Worth — прилагательное, после которого стоит только герундий: it is worth doing something. Здесь оборот take something into account («принимать во внимание») переходит в форму taking: It is not worth taking this information into account.", "w": ["worth не вводит придаточное предложение с if.", "", "после worth не бывает ни инфинитива, ни связки be; нужен чистый герундий.", "totake — слитное написание, орфографическая ошибка, и инфинитив после worth всё равно невозможен."], "k": "Worth doing — единственная форма. Никаких to и никаких придаточных после worth."},
{"id": "en-0023", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["отношение между величинами двух чисел или количеств", "величина или уровень, который можно измерить либо сравнить с другой величиной", "число повторений периодического процесса за единицу времени", "часть или доля целого", "деятельность, связанная с управлением компанией, школой или иной организацией", "скорость, с которой кто-либо или что-либо идёт, бежит или движется"], "poolru": {"-": "нет подходящего понятия", "administration": "управление, административная работа", "degree": "степень; учёная степень", "pace": "темп, скорость", "ratio": "соотношение"}, "o": [], "a": [], "pairs": [{"l": "a relationship between the sizes of two numbers or amounts", "r": "ratio"}, {"l": "an amount or level that can be measured or compared to another amount or level", "r": "degree"}, {"l": "the number of repetitions of a periodic process in a unit of time", "r": "-"}, {"l": "a part or share of a whole", "r": "-"}, {"l": "the activities that relate to running a company, school, or other organization", "r": "administration"}, {"l": "the speed at which somebody/something walks, runs or moves", "r": "pace"}], "pool": ["-", "administration", "degree", "pace", "ratio"], "ans": "", "img": null, "oimg": [], "e": "ratio — соотношение двух величин (2:1); degree — уровень, который можно измерить и сравнить с другим; administration — деятельность по управлению организацией; pace — скорость движения, темп. Определение 3 описывает frequency (частоту), определение 4 — portion или proportion (долю целого); в списке их нет.", "w": [], "k": "ratio — отношение двух чисел, rate — частота или ставка. Здесь rate нет, поэтому строка про частоту остаётся без пары."},
{"id": "en-0024", "t": 4, "ty": "one", "q": "I have never seen ... an interesting film.", "qru": "Я никогда не видел такого интересного фильма.", "oru": ["such — такой (перед существительным с прилагательным)", "so — настолько (перед прилагательным без существительного)", "very — очень", "too — слишком"], "pairsru": [], "poolru": {}, "o": ["such", "so", "very", "too"], "a": [0], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Порядок such + a/an + прилагательное + существительное: such an interesting film. Существительное film в предложении есть, поэтому нужен именно such.", "w": ["", "so сочетается с прилагательным без существительного: the film was so interesting. Со связкой «артикль + существительное» so не работает.", "very усиливает прилагательное, но не может стоять перед артиклем: получилось бы a very interesting film.", "too означает «слишком» и меняет смысл на отрицательный, а также требует того же порядка, что very."], "k": "Есть существительное — such a good film. Нет существительного — so good. Артикль лепится к such, а не наоборот."},
{"id": "en-0025", "t": 7, "ty": "one", "q": "Where is your father? – He is somewhere ... .", "qru": "Где твой отец? — Он где-то в доме.", "oru": ["home — дома (наречие, без предлога)", "at house — «у дома»; правильное сочетание — at home", "in the house — в доме, внутри здания", "in the home — в домашней обстановке, в быту (обобщённо)"], "pairsru": [], "poolru": {}, "o": ["home", "at house", "in the house", "in the home"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Речь о местонахождении внутри здания, поэтому нужен предлог места и house как «строение»: He is somewhere in the house — «он где-то в доме».", "w": ["home в значении «дома» употребляется без предлога (he is at home / he is home), но с somewhere не сочетается.", "at house — грамматическая ошибка: house требует артикля (at the house), да и at указывает на точку, а не на «внутри».", "", "in the home — «в семье, в быту» как социальный институт (violence in the home); про физическое местонахождение так не говорят."], "k": "House — здание, home — очаг. «Где-то внутри здания» — in the house."},
{"id": "en-0026", "t": 2, "ty": "one", "q": "In the past few years the fast development of communications ... orders ... from all over the country.", "qru": "За последние несколько лет быстрое развитие средств связи позволило биржам гораздо легче привлекать заказы со всей страны.", "oru": ["has allowed to attract … more easier — «позволило привлекать» без указания кому, и двойная степень сравнения", "has permitted stock exchanges to attract … more easily — позволило биржам привлекать … легче", "permitted stock exchanges to attract … much more easier — то же, но в простом прошедшем и с двойной степенью", "allowed stock exchanges attracting … much more easily — allow с формой на -ing вместо инфинитива"], "pairsru": [], "poolru": {}, "o": ["has allowed to attract ... more easier", "has permitted stock exchanges to attract ... more easily", "permitted stock exchanges to attract ... much more easier", "allowed stock exchanges attracting ... much more easily"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Permit и allow строятся одинаково: permit somebody to do something. Дополнение обязательно, поэтому has permitted stock exchanges to attract. Обстоятельство относится к глаголу attract, значит нужно наречие easily, а его сравнительная степень — more easily. Маркер In the past few years требует Present Perfect.", "w": ["allow без дополнения не употребляется (нужно allow somebody to do), и more easier — двойная сравнительная степень.", "", "Past Simple не согласуется с In the past few years, и снова ошибка more easier.", "после allow somebody идёт to-инфинитив, а не -ing; кроме того, Past Simple здесь неуместен."], "k": "In the past few years → Present Perfect. Easier уже сравнительная степень, more к ней не приставляют."},
{"id": "en-0027", "t": 6, "ty": "one", "q": "This seismograph is an extremely ... instrument.", "qru": "Этот сейсмограф — чрезвычайно чувствительный прибор.", "oru": ["sensitive — чувствительный, реагирующий на малейшее воздействие", "sensible — здравомыслящий, разумный", "sensual — чувственный, телесный", "sensuous — приятный для чувств, эстетически привлекательный"], "pairsru": [], "poolru": {}, "o": ["sensitive", "sensible", "sensual", "sensuous"], "a": [0], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Sensitive — чувствительный, реагирующий на малейшее воздействие. Именно это свойство важно для сейсмографа: он улавливает слабые колебания земной коры.", "w": ["", "sensible — «благоразумный, здравомыслящий»; относится к человеку или решению, а не к прибору.", "sensual — «чувственный» в смысле телесных удовольствий.", "sensuous — «услаждающий чувства», об искусстве и эстетическом впечатлении."], "k": "sensitive — чувствительный прибор или кожа, sensible — разумный человек или разумное решение."},
{"id": "en-0028", "t": 7, "ty": "one", "q": "I can't join you because I'm trying to sort ... things with IT.", "qru": "Я не могу к вам присоединиться, потому что пытаюсь уладить кое-какие дела с ИТ-отделом.", "oru": ["sort about — такого фразового глагола нет", "sort off — такого фразового глагола нет", "sort out — уладить, разобраться с чем-либо", "sort on — такого фразового глагола нет"], "pairsru": [], "poolru": {}, "o": ["about", "off", "out", "on"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Sort out — фразовый глагол «уладить, разобраться, привести в порядок»: sort things out with IT — «утрясти вопросы с айтишниками».", "w": ["sort about не существует.", "sort off не существует.", "", "sort on не существует; on со словом sort не сочетается."], "k": "Sort out — «разрулить»: out здесь означает «вытащить порядок наружу», как и в make out, work out, figure out."},
{"id": "en-0029", "t": 7, "ty": "one", "q": "When you are at lecture, it is useful to ... the most important points.", "qru": "Когда вы на лекции, полезно записывать самые важные мысли.", "oru": ["clear — прояснять, очищать", "put down — записывать", "write on — писать на поверхности; продолжать писать", "notify — официально уведомлять"], "pairsru": [], "poolru": {}, "o": ["clear", "put down", "write on", "notify"], "a": [1], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Put down — «записать, занести на бумагу». На лекции полезно фиксировать самые важные положения: put down the most important points.", "w": ["clear — «прояснить, очистить»; дополнение points с ним не сочетается в этом значении.", "", "write on — «писать на чём-либо» или «продолжать писать»; записать что-то в тетрадь так не скажут (нужно write down).", "notify — «уведомить кого-то», требует адресата, а не содержания."], "k": "Put down = write down = записать. Down — «вниз, на бумагу»."},
{"id": "en-0030", "t": 7, "ty": "one", "q": "Secondary schools offer a wide ... of subjects.", "qru": "Средние школы предлагают широкий выбор предметов.", "oru": ["range — набор, диапазон, выбор", "least — наименьший", "type — тип, разновидность", "field — область, сфера; поле"], "pairsru": [], "poolru": {}, "o": ["range", "least", "type", "field"], "a": [0], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "A wide range of — устойчивое сочетание «широкий спектр, широкий выбор». Школы предлагают большой набор предметов на выбор.", "w": ["", "least — превосходная степень от little; с артиклем a и предлогом of такой конструкции нет.", "type — «тип, разновидность»; a wide type не говорят, типов бывает много, а не «широкий».", "field — «область знаний»; a wide field of subjects — несочетаемо, поле бывает у одной дисциплины, а не у их набора."], "k": "A wide range of — «широкий спектр». Range про диапазон, field про одну область."},
{"id": "en-0031", "t": 1, "ty": "one", "q": "If the government ... the banks, they ... .", "qru": "Если правительство не поможет банкам, они не выживут.", "oru": ["does not help … will not survive — не поможет … не выживут (реальное условие)", "does not help … wouldn't survived — не поможет … «не выжили бы», в несуществующей форме", "didn't help … wouldn't survived — не помогло бы … в несуществующей форме", "didn't help … will not survive — не помогло бы … не выживут, смешение двух типов условия"], "pairsru": [], "poolru": {}, "o": ["does not help ... will not survive", "does not help ... wouldn't survived", "didn't help ... wouldn't survived", "didn't help ... will not survive"], "a": [0], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Первый тип условного предложения — реальное условие в будущем: в придаточном Present Simple, в главном will + инфинитив. If the government does not help the banks, they will not survive — «если государство не поможет банкам, они не выживут».", "w": ["", "wouldn't survived — невозможная форма: после would идёт инфинитив без окончания (wouldn't survive).", "та же ошибка с wouldn't survived; кроме того, didn't help относится к прошлому и не сочетается с реальным прогнозом.", "смешение типов: Past Simple в придаточном и will в главном одновременно не употребляются."], "k": "Первый тип: if + Present Simple, will + инфинитив. После would никогда не бывает третьей формы."},
{"id": "en-0032", "t": 2, "ty": "one", "q": "Why ... to do these obvious things?", "qru": "Зачем постоянно спрашивать у меня разрешения на такие очевидные вещи?", "oru": ["do you keep asking for a permission — «зачем вы постоянно просите разрешение», с лишним артиклем a", "to keep ask for a permit — после keep нужен герундий; permit — это пропуск, документ", "keep asking for my permission — постоянно спрашивать моего разрешения", "keep to ask for permit — после keep не бывает инфинитива"], "pairsru": [], "poolru": {}, "o": ["do you keep asking for a permission", "to keep ask for a permit", "keep asking for my permission", "keep to ask for permit"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "После keep всегда идёт герундий: keep asking. Permission — неисчисляемое существительное и артикля a не берёт. Why с голым инфинитивом образует риторический вопрос-упрёк: Why keep asking for my permission to do these obvious things? — «зачем всё время спрашивать у меня разрешения на такие очевидные вещи?»", "w": ["a permission — ошибка: permission неисчисляемо и с неопределённым артиклем не употребляется.", "после keep нужен герундий, а не инфинитив, и частица to перед keep здесь лишняя.", "", "снова инфинитив после keep вместо герундия; кроме того, permit — это письменное разрешение-документ, а не согласие человека."], "k": "Keep doing — только герундий. Permission неисчисляемо: никакого a permission."},
{"id": "en-0033", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["всё, что причинно влияет на результат", "возможность будущего успеха", "суждение, выражающее мнение на основе неполных данных", "число или соотношение (величина на шкале измерения), выведенное из ряда наблюдаемых фактов", "резкое несогласие", "систематическое изучение с целью установить факты"], "poolru": {"-": "нет подходящего понятия", "factor": "фактор", "indicator": "показатель, индикатор", "prospect": "перспектива", "research": "исследование"}, "o": [], "a": [], "pairs": [{"l": "anything that contributes causally to a result", "r": "factor"}, {"l": "the possibility of future success", "r": "prospect"}, {"l": "a message expressing an opinion based on incomplete evidence", "r": "-"}, {"l": "a number or ratio (a value on a scale of measurement) derived from a series of observed facts", "r": "indicator"}, {"l": "strong disagreement", "r": "-"}, {"l": "systematic investigation to establish facts", "r": "research"}], "pool": ["-", "factor", "indicator", "prospect", "research"], "ans": "", "img": null, "oimg": [], "e": "factor — то, что причинно влияет на результат; prospect — перспектива, возможность будущего успеха; indicator — числовой показатель, выведенный из ряда наблюдений; research — систематическое исследование ради установления фактов. Определение 3 описывает speculation (суждение на неполных данных), определение 5 — dispute или controversy; в списке их нет.", "w": [], "k": "factor влияет, indicator измеряет. Один — причина, другой — число на шкале."},
{"id": "en-0034", "t": 7, "ty": "one", "q": "When you criticize a subordinate, it is better to make constructive suggestions rather than just point out ... .", "qru": "Критикуя подчинённого, лучше вносить конструктивные предложения, а не просто указывать на недостатки.", "oru": ["futures — фьючерсы; варианты будущего", "points — пункты, моменты", "drawbacks — недостатки, минусы", "advantages — преимущества"], "pairsru": [], "poolru": {}, "o": ["futures", "points", "drawbacks", "advantages"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Предложение построено на противопоставлении: конструктивные предложения — лучше, чем простое указание на недостатки. Drawbacks — минусы, слабые стороны; point out drawbacks — «тыкать в недостатки».", "w": ["futures — либо «фьючерсы» как биржевой термин, либо неверная форма множественного числа от future.", "points — «моменты, пункты»; без определения непонятно, что именно, и противопоставления с suggestions не выходит.", "", "advantages — «преимущества»; указывать на достоинства при критике подчинённого нелогично, противопоставление ломается."], "k": "Критикуешь — указываешь на drawbacks. Rather than противопоставляет полезное (suggestions) бесполезному (drawbacks)."},
{"id": "en-0035", "t": 7, "ty": "one", "q": "These figures ... a peak in 2015 when over 2 million new machines were sold.", "qru": "Эти показатели достигли пика в 2015 году, когда было продано более 2 миллионов новых машин.", "oru": ["increased — увеличились", "got — получили; добрались", "rose — выросли, поднялись", "reached — достигли"], "pairsru": [], "poolru": {}, "o": ["increased", "got", "rose", "reached"], "a": [3], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Reach a peak — устойчивое сочетание «достичь пика». Пик — это точка, которой достигают, поэтому нужен переходный глагол reach: These figures reached a peak in 2015.", "w": ["increased — непереходный в этом значении: показатели растут сами, но «увеличить пик» нельзя.", "got — слишком общий и с peak не сочетается; было бы got to a peak, но предлога в задании нет.", "rose — тоже непереходный: rise требует предлога (rose to a peak).", ""], "k": "Reach a peak — без предлога. Rise и increase растут сами, а пика именно достигают."},
{"id": "en-0036", "t": 0, "ty": "one", "q": "By the end of the week Jane ... the financial report for three weeks and it ... .", "qru": "К концу недели Джейн будет писать финансовый отчёт уже три недели, и он всё ещё не будет закончен.", "oru": ["will have been writing … still won't be finished — будет писать уже три недели … всё ещё не будет закончен", "is writing … won't be yet finished — пишет сейчас … ещё не будет закончен, с yet не на своём месте", "has been writing … won't still be finished — пишет уже (о настоящем) … с won't still вместо still won't", "will be writing … won't be finished yet — будет писать в тот момент … ещё не будет закончен"], "pairsru": [], "poolru": {}, "o": ["will have been writing ... still won't be finished", "is writing ... won't be yet finished", "has been writing ... won't still be finished", "will be writing ... won't be finished yet"], "a": [0], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "By the end of the week задаёт точку в будущем, а for three weeks — длительность к этой точке. Такое сочетание требует Future Perfect Continuous: will have been writing — «к концу недели Джейн будет писать отчёт уже три недели». Во второй части still в отрицании стоит перед вспомогательным глаголом: it still won't be finished.", "w": ["", "Present Continuous не выражает длительность к будущему моменту, и won't be yet finished — неверное место наречия yet.", "Present Perfect Continuous не сочетается с By the end of the week, а won't still be finished ставит still не туда.", "Future Continuous показывает действие в процессе, но не его протяжённость «уже три недели», хотя вторая часть здесь как раз корректна."], "k": "By + момент в будущем + for + срок = will have been doing. Still в отрицании идёт перед won't, а yet — в конец."},
{"id": "en-0037", "t": 8, "ty": "match", "q": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "qru": "Подберите по одному определению к каждому из данных понятий. Понятие, которое не имеет определения, обозначьте знаком «-»", "oru": [], "pairsru": ["одинаковый во многих местах или у многих людей", "очень важный и сильно влияющий на других людей или на другие вещи", "существующий или происходящий внутри человека, предмета, организации, места или страны", "полный идей и увлечённости", "определённый способ мышления, особенно разумный и основанный на здравом суждении", "относящийся к тому, как устроены части системы или предмета"], "poolru": {"-": "нет подходящего понятия", "common": "общий, распространённый", "internal": "внутренний", "key": "ключевой", "structural": "структурный"}, "o": [], "a": [], "pairs": [{"l": "the same in a lot of places or for a lot of people", "r": "common"}, {"l": "very important and having a lot of influence on other people or things", "r": "key"}, {"l": "existing or happening inside a person, object, organization, place, or country", "r": "internal"}, {"l": "having a lot of ideas and enthusiasm", "r": "-"}, {"l": "a particular way of thinking, especially one that is reasonable and based on good judgement", "r": "-"}, {"l": "relating to the way in which parts of a system or object are arranged", "r": "structural"}], "pool": ["-", "common", "internal", "key", "structural"], "ans": "", "img": null, "oimg": [], "e": "common — одинаковый во многих местах или для многих людей; key как прилагательное — ключевой, определяющий; internal — внутренний; structural — относящийся к устройству системы. Определение 4 описывает creative, определение 5 вообще определяет существительное (a way of thinking — это rationale или common sense), а в списке только прилагательные; обе строки получают прочерк.", "w": [], "k": "Все понятия здесь — прилагательные. Если определение начинается с «a particular way of ...», это существительное, и пары не будет."},
{"id": "en-0038", "t": 6, "ty": "one", "q": "Collating all these pages is extremely slow and ... work.", "qru": "Раскладывать все эти страницы по порядку — крайне медленная и трудоёмкая работа.", "oru": ["exciting — увлекательный", "hardy — выносливый, стойкий", "laborious — трудоёмкий, кропотливый", "hardly — едва, почти не (наречие)"], "pairsru": [], "poolru": {}, "o": ["exciting", "hardy", "laborious", "hardly"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Laborious — трудоёмкий, кропотливый, требующий долгих усилий. Разбор и подборка страниц — работа медленная и нудная, поэтому slow and laborious work.", "w": ["exciting — «увлекательный»; противоречит slow и общему смыслу жалобы.", "hardy — «выносливый, морозостойкий»; говорят о людях и растениях, не о работе.", "", "hardly — наречие «едва, почти не»; в позиции определения к work наречие стоять не может."], "k": "Laborious — от labour, «трудоёмкий». Hardly — это не «трудно», а «едва»."},
{"id": "en-0039", "t": 5, "ty": "one", "q": "... unemployed.", "qru": "Чем лучше человек образован, тем меньше вероятность, что он окажется безработным.", "oru": ["«Чем лучше образованные люди будут, тем менее вероятно они будут» — нарушены порядок слов и согласование", "«Чем лучше образован человек, тем менее маловероятно…» — unlikely переворачивает смысл на противоположный", "Чем лучше человек образован, тем меньше вероятность, что он окажется", "Тот же смысл, но с инверсией, недопустимой в этой конструкции"], "pairsru": [], "poolru": {}, "o": ["The best educated people will be, the least likely they will be", "The better educated a person will be, the less unlikely a person will be the", "The better educated one is, the less likely one is to be", "The better educated is one, the less likely is he to be"], "a": [2], "pairs": [], "pool": [], "ans": "", "img": null, "oimg": [null, null, null, null], "e": "Конструкция «the + сравнительная степень ..., the + сравнительная степень ...» выражает пропорциональную зависимость. Обе части идут с прямым порядком слов и, как правило, в Present Simple, даже когда речь о будущем: The better educated one is, the less likely one is to be unemployed — «чем лучше человек образован, тем меньше вероятность, что он окажется безработным».", "w": ["best и least — превосходная степень; в этой конструкции нужна сравнительная.", "less unlikely переворачивает смысл на противоположный, и в конце повисает лишний артикль the.", "", "инверсия is one и is he в этой конструкции не употребляется — порядок слов остаётся прямым."], "k": "The more..., the more... — обе части в сравнительной степени, прямой порядок слов и Present Simple вместо будущего."},
];
